import{_ as i,o as a,c as n,a4 as l}from"./chunks/framework.B-wJupoK.js";const p="/assets/PixPin_2025-06-26_08-48-58.CLzGDdRY.gif",e="/assets/PixPin_2025-06-26_10-08-37.B9shLcmD.gif",h="/assets/image-20250626090210427.CBEFww7g.png",t="/assets/image-20250626090220294.DgZoGpfO.png",k="/assets/image-20250626111932624.7mXk1U7w.png",r="/assets/image-20250622200325374.BLr7GNE1.png",u=JSON.parse("{\"title\":\"HarmonyOS 组件复用 @ReusableV2装饰器的基本使用2\",\"description\":\"\",\"frontmatter\":{},\"headers\":[],\"relativePath\":\"鸿蒙开发技巧/HarmonyOS 组件复用 @ReusableV2装饰器的基本使用2/HarmonyOS 组件复用 @ReusableV2装饰器的基本使用2.md\",\"filePath\":\"鸿蒙开发技巧/HarmonyOS 组件复用 @ReusableV2装饰器的基本使用2/HarmonyOS 组件复用 @ReusableV2装饰器的基本使用2.md\",\"lastUpdated\":1751381397000,\"__rawMarkdown\":\"# HarmonyOS 组件复用 @ReusableV2装饰器的基本使用2\\n\\n## 前言\\n\\n接上文 **HarmonyOS 组件复用 @ReusableV2装饰器的基本使用**\\n\\n\\n\\n上文已经介绍过了 **@ReusableV2** 的基本使用和生命周期，本文主要讲解**@ReusableV2**的使用场景\\n\\n## 使用场景\\n\\n如官网中所总结的，因为以下场景都经常伴随着组件的显示和隐藏，@ReusableV2常见的使用场景如下：\\n\\n1. 搭配 if 使用\\n2. 搭配 Repeat 使用\\n3. 搭配 ForEach 使用\\n4. 搭配 LazyForEach 使用\\n\\n\\n\\n\\n\\n## 搭配 if 使用\\n\\n```typescript\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local condition: boolean = true;\\n\\n  build() {\\n    Column() {\\n      Button('回收/复用').onClick(() => {\\n        this.condition = !this.condition;\\n      }) // 点击切换回收/复用状态\\n      if (this.condition) {\\n        ReusableV2Component()\\n      }\\n    }\\n  }\\n}\\n\\n@ReusableV2\\n@ComponentV2\\nstruct ReusableV2Component {\\n  @Local message: string = 'Hello World';\\n\\n  aboutToRecycle() {\\n    console.log('ReusableV2Component aboutToRecycle'); // 回收时被调用\\n  }\\n\\n  aboutToReuse() {\\n    console.log('ReusableV2Component aboutToReuse'); // 复用时被调用\\n  }\\n\\n  build() {\\n    Column() {\\n      Text(this.message)\\n    }\\n  }\\n}\\n```\\n\\n### 效果\\n\\n![PixPin_2025-06-26_08-48-58](assets/PixPin_2025-06-26_08-48-58.gif)\\n\\n\\n\\n\\n\\n## 搭配 Repeat each 使用 懒加载场景\\n\\nRepeat组件**懒加载**场景中，将会优先使用Repeat组件的缓存池，**正常滑动场景、更新场景不涉及组件的回收与复用**。当Repeat的缓存池需要扩充时将会向自定义组件要求新的子组件，此时如果复用池中有可复用的节点，将会进行复用。\\n\\n```typescript\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local condition: boolean = true;\\n  @Local simpleList: number[] = [];\\n\\n  aboutToAppear(): void {\\n    for (let i = 0; i < 100; i++) {\\n      this.simpleList.push(i)\\n    }\\n  }\\n\\n  build() {\\n    Column() {\\n      Button('改变condition').onClick(() => {\\n        this.condition = !this.condition;\\n      })\\n      if (this.condition) {\\n        // 此处仅做演示使用，让复用池中填充3个组件\\n        ReusableV2Component({ num: 0 })\\n        ReusableV2Component({ num: 0 })\\n        ReusableV2Component({ num: 0 })\\n      }\\n      List({ space: 10 }) {\\n        Repeat(this.simpleList)\\n          .virtualScroll()\\n          .each((obj: RepeatItem<number>) => {\\n            ListItem() {\\n              Column() {\\n                ReusableV2Component({ num: obj.item })\\n              }\\n            }\\n          })\\n      }.height('50%')\\n      .cachedCount(2)\\n    }\\n  }\\n}\\n\\n@ReusableV2\\n@ComponentV2\\nstruct ReusableV2Component {\\n  @Require @Param num: number;\\n\\n  aboutToAppear() {\\n    console.log('ReusableV2Component aboutToAppear');\\n  }\\n\\n  aboutToRecycle() {\\n    console.log('ReusableV2Component aboutToRecycle');\\n  }\\n\\n  aboutToReuse() {\\n    console.log('ReusableV2Component aboutToReuse');\\n  }\\n\\n  build() {\\n    Column() {\\n      Text(`${this.num}`).fontSize(50)\\n    }\\n  }\\n}\\n```\\n\\n### 效果\\n\\n![PixPin_2025-06-26_10-08-37](assets/PixPin_2025-06-26_10-08-37.gif)\\n\\n**步骤解释：**\\n\\n1. 正常滑动列表，不会触发组件的 **回收和复用**\\n2. 点击按钮，条件渲染 组件时，就会触发组件的回收和复用了\\n\\n\\n\\n### virtualScroll\\n\\nvirtualScroll 表示 虚拟列表，使用不使用virtualScroll的区别在于\\n\\n| 使用 virtualScroll                         | 不使用 virtualScroll                                         |\\n| ------------------------------------------ | ------------------------------------------------------------ |\\n| 预加载区的ListItem会在系统空闲时创建和布局 | 预加载区内的ListItem会在**首帧创建**，系统空闲时布局ListItem和创建ListItem内部的子结构 |\\n\\n**使用virtualScroll ：**\\n\\n![image-20250626090210427](assets/image-20250626090210427.png)\\n\\n**不使用virtualScroll ：**\\n\\n![image-20250626090220294](assets/image-20250626090220294.png)\\n\\n## 搭配 Repeat each 使用 非懒加载场景\\n\\nRepeat组件非懒加载场景中，会在删除/创建子树时触发回收/复用。\\n\\n```typescript\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local simpleList: number[] = [1, 2, 3, 4, 5];\\n  @Local condition: boolean = true;\\n\\n  build() {\\n    Column() {\\n      Button('删除/创建Repeat').onClick(() => {\\n        this.condition = !this.condition;\\n      })\\n      Button('增加元素').onClick(() => {\\n        this.simpleList.push(this.simpleList.length + 1);\\n      })\\n      Button('删除元素').onClick(() => {\\n        this.simpleList.pop();\\n      })\\n      Button('更改元素').onClick(() => {\\n        this.simpleList[0]++;\\n      })\\n      if (this.condition) {\\n        List({ space: 10 }) {\\n          Repeat(this.simpleList)\\n            .each((obj: RepeatItem<number>) => {\\n              ListItem() {\\n                Column() {\\n                  ReusableV2Component({ num: obj.item })\\n                }\\n              }\\n            })\\n        }\\n      }\\n    }\\n  }\\n}\\n\\n@ReusableV2\\n@ComponentV2\\nstruct ReusableV2Component {\\n  @Require @Param num: number;\\n\\n  aboutToAppear() {\\n    console.log('ReusableV2Component aboutToAppear');\\n  }\\n\\n  aboutToRecycle() {\\n    console.log('ReusableV2Component aboutToRecycle');\\n  }\\n\\n  aboutToReuse() {\\n    console.log('ReusableV2Component aboutToReuse');\\n  }\\n\\n  build() {\\n    Column() {\\n      Text(`${this.num}`)\\n    }\\n  }\\n}\\n```\\n\\n![image-20250626111932624](assets/image-20250626111932624.png)\\n\\n\\n\\n操作步骤如下：\\n\\n1. 运行项目\\n\\n   ```\\n   触发 aboutToAppear\\n   ```\\n\\n2. 增加元素\\n\\n   ```\\n   触发 aboutToAppear\\n   ```\\n\\n3. 删除元素\\n\\n   ```\\n   触发 aboutToRecycle\\n   ```\\n\\n4. 更改元素\\n\\n   ```\\n   无输出\\n   ```\\n\\n5. 删除/创建Repeat\\n\\n   ```\\n   触发 aboutToRecycle 和 aboutToReuse\\n   ```\\n\\n   \\n\\n\\n\\n## 搭配 Repeat 和 ForEach\\n\\n> 推荐开发者使用Repeat组件的非懒加载场景代替ForEach组件\\n\\n```typescript\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local simpleList: number[] = [0, 1, 2, 3, 4, 5];\\n  build() {\\n    Column() {\\n      ForEach(this.simpleList, (num: number, index) => {\\n        Row() {\\n          Button('点击修改').onClick(()=>{this.simpleList[index]++;})\\n          ReusableV2Component({ num: num })\\n        }\\n      }) // 每次修改完key发生变化\\n    }\\n  }\\n}\\n@ReusableV2\\n@ComponentV2\\nstruct ReusableV2Component {\\n  @Require @Param num: number;\\n  aboutToAppear() {\\n    console.log('ReusableV2Component aboutToAppear', this.num); // 创建时触发\\n  }\\n  aboutToRecycle() {\\n    console.log('ReusableV2Component aboutToRecycle', this.num); // 回收时触发\\n  }\\n  aboutToReuse() {\\n    console.log('ReusableV2Component aboutToReuse', this.num); // 复用时触发\\n  }\\n  build() {\\n    Column() {\\n      Text(`child: ${this.num}`)\\n    }\\n  }\\n}\\n```\\n\\n\\n\\n## 搭配 Repeat 和 LazyForEach\\n\\n> 推荐开发者使用Repeat组件的懒加载场景代替LazyForEach组件\\n\\n```typescript\\nclass BasicDataSource implements IDataSource {\\n  private listeners: DataChangeListener[] = [];\\n  private originDataArray: StringData[] = [];\\n\\n\\n  public totalCount(): number {\\n    return 0;\\n  }\\n\\n\\n  public getData(index: number): StringData {\\n    return this.originDataArray[index];\\n  }\\n\\n\\n  registerDataChangeListener(listener: DataChangeListener): void {\\n    if (this.listeners.indexOf(listener) < 0) {\\n      console.info('add listener');\\n      this.listeners.push(listener);\\n    }\\n  }\\n\\n\\n  unregisterDataChangeListener(listener: DataChangeListener): void {\\n    const pos = this.listeners.indexOf(listener);\\n    if (pos >= 0) {\\n      console.info('remove listener');\\n      this.listeners.splice(pos, 1);\\n    }\\n  }\\n\\n\\n  notifyDataReload(): void {\\n    this.listeners.forEach(listener => {\\n      listener.onDataReloaded();\\n    })\\n  }\\n\\n\\n  notifyDataAdd(index: number): void {\\n    this.listeners.forEach(listener => {\\n      listener.onDataAdd(index);\\n    })\\n  }\\n\\n\\n  notifyDataChange(index: number): void {\\n    this.listeners.forEach(listener => {\\n      listener.onDataChange(index);\\n    })\\n  }\\n\\n\\n  notifyDataDelete(index: number): void {\\n    this.listeners.forEach(listener => {\\n      listener.onDataDelete(index);\\n    })\\n  }\\n\\n\\n  notifyDataMove(from: number, to: number): void {\\n    this.listeners.forEach(listener => {\\n      listener.onDataMove(from, to);\\n    })\\n  }\\n\\n\\n  notifyDatasetChange(operations: DataOperation[]): void {\\n    this.listeners.forEach(listener => {\\n      listener.onDatasetChange(operations);\\n    })\\n  }\\n}\\n\\n\\nclass MyDataSource extends BasicDataSource {\\n  private dataArray: StringData[] = [];\\n\\n\\n  public totalCount(): number {\\n    return this.dataArray.length;\\n  }\\n\\n\\n  public getData(index: number): StringData {\\n    return this.dataArray[index];\\n  }\\n\\n\\n  public addData(index: number, data: StringData): void {\\n    this.dataArray.splice(index, 0, data);\\n    this.notifyDataAdd(index);\\n  }\\n\\n\\n  public pushData(data: StringData): void {\\n    this.dataArray.push(data);\\n    this.notifyDataAdd(this.dataArray.length - 1);\\n  }\\n}\\n\\n\\n@ObservedV2\\nclass StringData {\\n  @Trace message: string;\\n  constructor(message: string) {\\n    this.message = message;\\n  }\\n}\\n\\n\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  data: MyDataSource = new MyDataSource(); // 数据源\\n\\n\\n  aboutToAppear() {\\n    for (let i = 0; i <= 200; i++) {\\n      this.data.pushData(new StringData('Hello' + i));\\n    }\\n  }\\n  build() {\\n    List({ space: 3 }) {\\n      LazyForEach(this.data, (item: StringData, index: number) => {\\n        ListItem() {\\n          Column() {\\n            Text(item.message)\\n            ChildComponent({ data: item.message })\\n              .onClick(() => {\\n                item.message += '!'; // message为@Trace装饰的变量，可观察变化\\n              })\\n          }\\n        }\\n      })\\n    }.cachedCount(5)\\n  }\\n}\\n\\n\\n@ReusableV2\\n@ComponentV2\\nstruct ChildComponent {\\n  @Param @Require data: string;\\n  aboutToAppear(): void {\\n    console.log('ChildComponent aboutToAppear', this.data);\\n  }\\n  aboutToDisappear(): void {\\n    console.log('ChildComponent aboutToDisappear', this.data);\\n  }\\n  aboutToReuse(): void {\\n    console.log('ChildComponent aboutToReuse', this.data); // 复用时触发\\n  }\\n  aboutToRecycle(): void {\\n    console.log('ChildComponent aboutToRecycle', this.data); // 回收时触发\\n  }\\n  build() {\\n    Row() {\\n      Text(this.data).fontSize(50)\\n    }\\n  }\\n}\\n```\\n\\n## 关于我们\\n\\n[关于青蓝逐码组织](https://link.juejin.cn/?target=https%3A%2F%2Fwww.qinglanzhuma.cn%2F)\\n\\n如果你兴趣想要了解更多的鸿**蒙应用开发细节和最新资讯**，**甚至你想要做出一款属于自己的应用**！欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。\\n\\n![image-20250622200325374](assets/image-20250622200325374.png)\"}"),E={name:"鸿蒙开发技巧/HarmonyOS 组件复用 @ReusableV2装饰器的基本使用2/HarmonyOS 组件复用 @ReusableV2装饰器的基本使用2.md"};function d(g,s,c,y,b,o){return a(),n("div",null,[...s[0]||(s[0]=[l("",41)])])}const m=i(E,[["render",d]]);export{u as __pageData,m as default};
